SELECT
  count(*) AS total,
  count(*) FILTER (WHERE q.quality_review_status IN ('unverified','pending')) AS unv_pending,
  count(*) FILTER (WHERE q.id IN (SELECT id FROM v_safe_for_beta)) AS already_vsafe,
  count(*) FILTER (WHERE q.pipeline_metadata::jsonb ? 'demoted_at') AS has_demoted,
  count(*) FILTER (WHERE q.pipeline_metadata::jsonb ? 'ai_extras'
        AND (q.pipeline_metadata::jsonb->'ai_extras') ? 'topic_match_quality'
        AND ((q.pipeline_metadata::jsonb->'ai_extras')->>'topic_match_quality')='fallback') AS fallback,
  count(*) FILTER (WHERE q.pipeline_metadata::jsonb ? 'match_tier'
        AND (q.pipeline_metadata::jsonb->>'match_tier') IN ('tier1_page_inline','tier1b_position_page_inline')) AS tier1block,
  count(*) FILTER (WHERE q.exam_type='AYT' AND q.subject_area='EDEBIYAT') AS ayt_edeb,
  count(*) FILTER (WHERE q.is_active) AS active
FROM t JOIN question_bank q ON q.id::text = t.id;
